import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './cta.css';

/**
 * B49 · CallToAction — the last row of a public page, and the only one that
 * asks for anything. One job: name the one act the page wants.
 *
 * Everything above it states; this asks. That is why it holds exactly ONE
 * primary. B10's rule is not relaxed on the public surface — it is at its
 * most binding here, because a page that asks for two things has asked for
 * neither. `actions` is a slot rather than a `label`/`onClick` pair so a
 * ghost may stand beside the primary; the discipline is the caller's, and
 * the prop doc is where it is written down.
 *
 * There is no `urgency`, no `countdown` and no `scarcity` prop, and there
 * never will be: 76° speaks like a competent colleague (A3), and a clock
 * that pressures the reader is the opposite of that. There is no `form`
 * slot either — a form is a page, or a B24 Plate.
 */
export interface CallToActionProps {
  /** The ask, at display size. Not a slogan — name the act's object (A3). */
  title: string;
  /** ONE sentence: what happens after the click, or what it costs. */
  statement?: string;
  /** ONE primary. A ghost beside it is permitted; a second primary is not. */
  actions: ReactNode;
  /** A mono line under the actions: the terms, the trial length, the card requirement. */
  note?: string;
  /** 'paper' — a card on the wall. 'band' — the ink surface, edge to edge. */
  tone?: 'paper' | 'band';
  /** 2 by default: a page's h1 is its Masthead (B47), and levels never skip (A4). */
  headingLevel?: 2 | 3;
  className?: string;
}

export function CallToAction({
  title,
  statement,
  actions,
  note,
  tone = 'paper',
  headingLevel = 2,
  className,
}: CallToActionProps) {
  const Heading = headingLevel === 3 ? 'h3' : 'h2';

  return (
    /* `sv-band` rides along on the ink tone because the re-toning already
       exists system-wide: button.css re-borders `.sv-band .sv-btn--ghost` in
       --sv-band-line, and base.css turns `.sv-band :focus-visible` white. A
       ghost and a focus ring inside this row therefore need no rules of their
       own — verified against both files, so cta.css writes none.
       A real <section> carries the row, with the heading inside it and no
       aria-label beside it: the heading is the name already, and a second one
       would only give one row two. */
    <section className={cx('sv-cta', `sv-cta--${tone}`, tone === 'band' && 'sv-band', className)}>
      <div className="sv-cta__text">
        <Heading className="sv-cta__title">{title}</Heading>
        {statement && <p className="sv-cta__statement">{statement}</p>}
      </div>
      <div className="sv-cta__side">
        <div className="sv-cta__actions">{actions}</div>
        {/* The terms sit UNDER the button, in the mono metadata voice — the
            cost is stated where the click is, not in a footnote nobody reads. */}
        {note && <p className="sv-cta__note sv-mono">{note}</p>}
      </div>
    </section>
  );
}

/* B49 · CallToAction — the ask. One primary, stated once, at display size. */

@layer sv-components {
  /* The ask on the left, the act on the right, centred to each other: the
     eye finishes the sentence exactly where the button is. */
  .sv-cta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sv-s7);
    padding: var(--sv-s8);
    border-radius: var(--sv-r);
  }

  /* min-width:0 so a long unbroken word shrinks the column instead of
     pushing the actions off the row (C7). */
  .sv-cta__text {
    min-width: 0;
  }

  /* The one display step the public surface may speak in at this scale
     (rule 17). It clamps to 21px at 320px — the size the same line takes in
     the product ramp — so the page degrades INTO the system, not out of it. */
  .sv-cta__title {
    font-size: var(--sv-display-3);
    line-height: 1.15;
    font-weight: 800;
    letter-spacing: -0.025em;
    text-wrap: balance;
  }

  /* Capped near 52ch because a measure wider than that stops being one
     sentence to read and starts being a paragraph to skim. */
  .sv-cta__statement {
    margin-top: var(--sv-s3);
    max-width: 52ch;
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--sv-ink-soft);
  }

  .sv-cta__side {
    display: flex;
    flex: none;
    flex-direction: column;
    align-items: flex-end;
    gap: var(--sv-s3);
  }

  .sv-cta__actions {
    display: flex;
    align-items: center;
    gap: var(--sv-s2);
  }

  /* The terms carry real information — what it costs, whether a card is
     needed — so they take the soft step, never the faint one (C2). */
  .sv-cta__note {
    color: var(--sv-ink-soft);
    text-align: right;
  }

  /* ---- tone="paper" · an ordinary card on the wall (A4) ---- */

  .sv-cta--paper {
    background: var(--sv-paper);
    box-shadow: var(--sv-shadow);
  }

  /* ---- tone="band" · the ink surface ----
     No shadow, and the omission is the rule: ink is the wall's opposite,
     not a card sitting on it. Nothing here floats.
     The mark on ink is --sv-on-dark, never --sv-paper: paper inverts with
     the mode and the band does not, so paper-as-text would collapse the
     pair on dark (rule 16). */

  .sv-cta--band {
    background: var(--sv-band);
  }

  .sv-cta--band .sv-cta__title {
    color: var(--sv-on-dark);
  }

  .sv-cta--band .sv-cta__statement,
  .sv-cta--band .sv-cta__note {
    color: var(--sv-band-soft);
  }

  /* ---- The floor ----
     Below 720px the row stacks and the act stops being a right-hand
     accessory: it takes the full width, at the reading order's end, where
     a thumb already is. Nothing is dropped and nothing scrolls sideways. */

  @media (max-width: 720px) {
    .sv-cta {
      flex-direction: column;
      align-items: stretch;
      gap: var(--sv-s6);
      padding: var(--sv-s7);
    }

    .sv-cta__side {
      align-items: stretch;
    }

    /* Column, not a wrapping row: two half-width buttons on a 320px screen
       are two two-line clickables. Each one gets the whole width. */
    .sv-cta__actions {
      flex-direction: column;
      align-items: stretch;
    }

    .sv-cta__note {
      text-align: left;
    }
  }
}
